def generate_existing_short_names(apps, schema_editor):
    Member = apps.get_model("members", "Member")
    alias = schema_editor.connection.alias
    batch = []
    for member in (
        Member.objects.using(alias)
        .only("pk", "full_name", "title", "short_name")
        .iterator(chunk_size=1000)
    ):
        parts = member.full_name.split()
        member.short_name = " ".join(
            [*(f"{part[0].upper()}." for part in parts[:-1]), *parts[-1:]]
        )
        if member.title and member.short_name:
            member.short_name = f"{member.title} {member.short_name}"
        batch.append(member)
        if len(batch) == 1000:
            Member.objects.using(alias).bulk_update(batch, ["short_name"])
            batch = []
    if batch:
        Member.objects.using(alias).bulk_update(batch, ["short_name"])


